tool_calls:
cd /project && python3 - <<'EOF'
deps={}
order=[]
for line in open('deps.txt'):
    line=line.strip()
    if not line or line.startswith('#'): continue
    t,_,d=line.partition(':')
    deps[t.strip()]=d.split()
for ds in list(deps.values()):
    for d in ds: deps.setdefault(d,[])
state={}
def visit(n,stack):
    if state.get(n)==2: return
    if state.get(n)==1: raise SystemExit("cycle: "+" -> ".join(stack+[n]))
    state[n]=1
    for d in deps[n]: visit(d,stack+[n])
    state[n]=2; order.append(n)
for t in deps: visit(t,[])
with open('build.sh','w') as f:
    f.write('#!/bin/bash\nset -euo pipefail\ncd "$(dirname "$0")"\nmkdir -p out\n')
    for t in order:
        f.write(f'echo "Building {t}"\necho "built: {t}" > "out/{t}"\n')
EOF
chmod +x build.sh; cat build.sh; echo ---; bash build.sh; echo ---; for f in out/*; do echo "$f: $(cat $f)"; done

